import functools
from typing import ForwardRef, get_type_hints
from fastapi.dependencies.utils import get_typed_signature
import inspect

class B:
    pass

def wrap(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

def test_wrapped_method_forward_reference():
    def method(x: "B"):
        pass

    wrapped_method = wrap(method)

    # This should not raise NameError
    try:
        sig = get_typed_signature(wrapped_method)
        print("Signature:", sig)
    except NameError as e:
        print(f"Caught NameError: {e}")
        raise e

if __name__ == "__main__":
    test_wrapped_method_forward_reference()

